package net.officefloor.hq.app.claim;

/** Where a claim is in its life: DRAFT -> OPEN -> SETTLED, or DRAFT/OPEN -> VOID. Only OPEN and
 *  SETTLED claims count toward the totals; SETTLED and VOID are final. */
public enum ClaimStatus {
    DRAFT, OPEN, SETTLED, VOID
}
EOF
cat > $J/ClaimAction.java <<'EOF'
package net.officefloor.hq.app.claim;

import java.util.Set;

/** A status change, named as in the path: the statuses it may be taken from, the status it moves
 *  the claim to and the audit event it writes. */
public enum ClaimAction {
    OPEN(Set.of(ClaimStatus.DRAFT), ClaimStatus.OPEN, "CLAIM_OPENED"),
    SETTLE(Set.of(ClaimStatus.OPEN), ClaimStatus.SETTLED, "CLAIM_SETTLED"),
    VOID(Set.of(ClaimStatus.DRAFT, ClaimStatus.OPEN), ClaimStatus.VOID, "CLAIM_VOIDED");

    private final Set<ClaimStatus> from;
    private final ClaimStatus to;
    private final String event;

    ClaimAction(Set<ClaimStatus> from, ClaimStatus to, String event) {
        this.from = from;
        this.to = to;
        this.event = event;
    }

    public boolean allowedFrom(ClaimStatus status) { return from.contains(status); }
    public ClaimStatus to() { return to; }
    public String event() { return event; }
}
EOF
cat > $J/ValidateClaimAction.java <<'EOF'
package net.officefloor.hq.app.claim;

import java.util.Locale;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class ValidateClaimAction {
    public void validate(@PathVariable("action") String action, Out<ClaimAction> actionOut)
            throws InvalidClaimException {
        try {
            actionOut.set(ClaimAction.valueOf(action.toUpperCase(Locale.ROOT)));
        } catch (IllegalArgumentException e) {
            throw new InvalidClaimException("No such claim action: " + action);
        }
    }
}
EOF
cat > $J/ApplyClaimAction.java <<'EOF'
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

/** Moves the claim to the action's status, refusing a change its current status does not allow. */
public class ApplyClaimAction {
    public void apply(@Val ClaimAction action, @Val Claim claim) throws InvalidClaimStatusException {
        if (!action.allowedFrom(claim.getStatus())) {
            throw new InvalidClaimStatusException(
                    "A " + claim.getStatus() + " claim cannot be moved to " + action.to() + ".");
        }
        claim.setStatus(action.to());
    }
}
EOF
cat > $J/InvalidClaimStatusException.java <<'EOF'
package net.officefloor.hq.app.claim;

/** The claim's status does not allow the requested change (SETTLED and VOID are final). */
public class InvalidClaimStatusException extends Exception {
    public InvalidClaimStatusException(String message) {
        super(message);
    }
}
EOF
cat > $J/HandleInvalidClaimStatus.java <<'EOF'
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleInvalidClaimStatus {
    public void handle(@Parameter InvalidClaimStatusException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.CONFLICT));
    }
}
EOF
cat > resources/officefloor/escalation/net.officefloor.hq.app.claim.InvalidClaimStatusException.yml <<'EOF'
handle:
  class: net.officefloor.hq.app.claim.HandleInvalidClaimStatus
EOF
cat > $J/AuditClaimStatus.java <<'EOF'
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the claim's status change once it is allowed and saved. */
public class AuditClaimStatus {
    public void audit(@Val ClaimAction action, @Val Claim claim,
            @RequestParam(value = "user", required = false) String user, PersonRepository people, Audit audit) {
        Person person = people.findById(claim.getSheetId(), claim.getPersonId());
        audit.record(action.event() + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate());
    }
}
EOF
D='resources/officefloor/rest/api/sheets/{sheetId}/claims/{claimId}'
mkdir -p "$D"
cat > "$D/{action}.POST.yml" <<'EOF'
# open | settle | void a claim. The audit line is written last, once the change is allowed and
# saved, so a refused change (an unknown action 400, a status that forbids it 409) writes none.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaimAction
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaimAction
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.AuditClaimStatus
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
EOF
